contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an arbitrary amount to forward to c.go
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // record owner and c balance before
        address ownerBefore = c.owner();
        uint cBalanceBefore = address(c).balance;

        // call go with provided amount, capture whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call: if it did not revert, C should have forwarded the msg.value to target and then transferred its balance to owner.
        // Observable effects: if call succeeded, c.balance must be zero and owner unchanged.
        // If call reverted, we do not require postconditions.
        assert(reverted || (address(c).balance == 0 && c.owner() == ownerBefore));
    }

    // Allow receiving Ether so the test contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an arbitrary amount to forward to c.go
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // observe before-values
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(c).balance;

        // General rule:
        // - owner never changes
        // - if call succeeded then C's balance is zero
        // - if call reverted then balance is unchanged
        assert(ownerBefore == ownerAfter && (reverted ? balanceAfter == balanceBefore : balanceAfter == 0));
    }

    receive() external payable {}
}

